inline const freeink::ui::BitmapRef* motiveById(const char* id) {
  if (!id) return nullptr;
  for (unsigned i = 0; i < sizeof(motives) / sizeof(motives[0]); ++i)
    if (std::strcmp(id, motivesIds[i]) == 0) return motives[i];
  return nullptr;
}
inline void draw(toybox::Screen& s, freeink::ui::Rect r, const freeink::ui::BitmapRef& art) {
  s.target().bitmap(r, art, freeink::ui::BitmapMode::Contain, freeink::ui::Paint::solid(freeink::ui::Color::Black));
}
